#ifndef __WSP_TEXT_H
#define __WSP_TEXT_H

#include "ch32x035.h"

#define TEXT_ADVANCE        (WSP_FONT_W + 1)    /* 1px gap between glyphs */

/* draw one glyph, returns the advance in pixels (0 width on missing chars) */
uint16_t text_char(uint16_t x, uint16_t y, char c, uint16_t color565);

/* draw a zero terminated string, returns the x position after the last glyph */
uint16_t text_draw(uint16_t x, uint16_t y, const char *s, uint16_t color565);

/* width in pixels of a whole string (advance * strlen - 1) */
uint16_t text_width(const char *s);

#endif /* __WSP_TEXT_H */
